document.addEventListener(`click`,e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||!(e.target instanceof Element))return;if(e.target.closest(`[data-social-share-print]`)){e.preventDefault(),window.print();return}let t=e.target.closest(`[data-social-share-popup]`);if(!t||!t.href)return;let n=window.open(``,`ss_share_dialog`,`width=626,height=436`);n&&(n.opener=null,n.location.href=t.href,e.preventDefault())});